"""Regression fixtures generated by the original JS core.js in Node.

No Node, browser or live WMS required to run these checks on a Windows build.
These numeric/string scenarios protect the Python translation against drift.
"""
import json
from pathlib import Path
import unittest
import prod_native_core as c
import prod_native_api as a


class NativeProdParity(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.f=json.loads((Path(__file__).parent/'prod_native_fixtures.json').read_text(encoding='utf-8'))
        cls.e=cls.f['expected']
        cls.stations=c.station_table()
        cls.ops=c.last_operator_by_station(cls.f['tasks'])
        cls.hours={'prev':c.hour_map(cls.f['previous']),'cur':c.hour_map(cls.f['current'])}
        cls.station_rows=c.build_station_rows(cls.f['stations'],cls.f['people'],cls.ops,cls.hours,cls.stations)

    def test_time_boundaries(self):
        now=self.f['now']
        self.assertEqual(c.hour_window(now),self.e['hourWindow'])
        self.assertEqual(c.hour_windows(now),self.e['hourWindows'])
        self.assertEqual(c.shift_window(now),self.e['shiftWindow'])
        self.assertEqual(c.default_task_range(now),self.e['defaultTaskRange'])

    def test_station_map_and_last_operator(self):
        self.assertEqual(c.station_ids(self.f['stations']),self.e['stationIds'])
        self.assertEqual(self.ops,self.e['lastOperatorByStation'])
        self.assertEqual(self.station_rows,self.e['stationRows'])

    def test_station_ranking(self):
        self.assertEqual(c.filter_station_rows(self.station_rows,'Check',150),self.e['checkBelow'])
        self.assertEqual(c.filter_station_rows(self.station_rows,'Check&Pack',150),self.e['checkPackBelow'])
        self.assertEqual(c.count_stations(self.station_rows,'Check'),self.e['countCheck'])

    def test_sort_staff_group(self):
        grouped=c.group_by_operator(self.station_rows)
        self.assertEqual(grouped,self.e['grouped'])
        self.assertEqual(c.filter_sort_persons(grouped['persons'],150),self.e['filteredSort'])

    def test_pack_assignments_and_rows(self):
        stations=c.build_pack_station_map(self.f['packTasks'])
        self.assertEqual(stations,self.e['packStationMap'])
        merged=c.merge_rows(self.f['people'],self.f['orders'],stations,self.hours,self.stations)
        self.assertEqual(merged,self.e['merged'])
        self.assertEqual(c.filter_pack_rows(merged,150),self.e['packBelow'])

    def test_build_people_aggregates_and_missing(self):
        self.assertEqual(c.build_people(self.f['inputPeople']),self.e['builtPeople'])

    def test_display_sort_does_not_mutate_original(self):
        original=json.dumps(self.station_rows,sort_keys=True)
        high=c.filtered_view(self.station_rows,'Check Station',150,show_all=True,ascending=False)
        low=c.filtered_view(self.station_rows,'Check Station',150,show_all=True,ascending=True)
        self.assertEqual([x['prod'] for x in high['rows']],list(reversed([x['prod'] for x in low['rows']])))
        self.assertEqual(json.dumps(self.station_rows,sort_keys=True),original)

    def test_bridge_query_shape_matches_original(self):
        generator=a.fetch_productivity(1700000000,1700003600,41,'order_count','individual','email@example.com')
        request=next(generator)
        self.assertEqual(request['type'],'WMS_POST')
        self.assertEqual(request['body'],{
            'from_time':1700000000,'to_time':1700003600,'task_type':41,
            'dim_type':'individual','query_column':'order_count','order_by_column_key':'',
            'order_type':'desc','staff_email':'','time_interval':3600,'pageno':1,
            'count':20,'user_email':'email@example.com'
        })
        with self.assertRaises(StopIteration) as done:
            generator.send({'success':True,'data':{'list':[{'staff_email':'X','productivity':10}],'total':1}})
        self.assertEqual(done.exception.value,[{'staff_email':'X','productivity':10}])

    def test_productivity_pagination_uses_original_page_size(self):
        gen=a.fetch_productivity(100,200,41)
        self.assertEqual(next(gen)['body']['pageno'],1)
        next_request=gen.send({'success':True,'data':{'list':[{'i':i} for i in range(20)],'total':25}})
        self.assertEqual(next_request['body']['pageno'],2)
        with self.assertRaises(StopIteration) as done:
            gen.send({'success':True,'data':{'list':[{'i':i} for i in range(20,25)],'total':25}})
        self.assertEqual(len(done.exception.value),25)

    def test_pack_task_pagination_stops_on_short_page(self):
        gen=a.fetch_pack_tasks()
        req=next(gen)
        self.assertIn('task_status=1',req['url'])
        with self.assertRaises(StopIteration) as done:
            gen.send({'success':True,'data':{'list':[{'id':1}],'total':1}})
        self.assertEqual(done.exception.value,[{'id':1}])

    def test_check_recent_stops_when_all_stations_have_operator(self):
        gen=a.fetch_checked_recent(100000,['CS00001'])
        req=next(gen)
        self.assertIn('complete_time_start=99701',req['url'])
        with self.assertRaises(StopIteration) as done:
            gen.send({'success':True,'data':{'list':[{'checked_station_id':'CS00001','operator':'a@b','done_time':99999}],'total':1}})
        self.assertTrue(done.exception.value['complete'])

if __name__=='__main__':unittest.main()
